 const [data,setData]=useState<{owner:string;role:BoardRole;item:BoardItem|null;items:z.infer<typeof summarySchema>[];next:string|null}|null>(null),[draft,setDraft]=useState<BoardDefinition|null>(null),[editing,setEditing]=useState(false),[busy,setBusy]=useState(false),[writeBusy,setWriteBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[pending,setPending]=useState<Pending|null>(null),[accepted,setAccepted]=useState<{scope:string;ack:z.infer<typeof writeSchema>['ack'];deleted:boolean}|null>(null),[cloneName,setCloneName]=useState(''),[scopeDraft,setScopeDraft]=useState(''),[refresh,setRefresh]=useState(0);
 const draftBaseline=useRef<string|null>(null),leaving=useRef(false),[sharePending,setSharePending]=useState(false);
 const shareAccessEpoch=useRef(0),mounted=useRef(false),serial=useRef(0),operation=useRef<AbortController|null>(null),writeOperation=useRef<AbortController|null>(null),writeLock=useRef(false),notified=useRef(false),focus=useRef<string|null>(null),pageBack=useRef<string[]>([]),uid=useId();
 const current=readEnabled&&data?.owner===owner?data:null,item=current?.item??null,writer=current!==null&&current.role!=='viewer',ownedPending=pending?.workspace===workspaceId&&pending.user===userId?pending:null,applied=item?(parsed?.scope??item.definition.scope):null;
 const dirty=()=>current!==null&&writer&&editing&&draft!==null&&JSON.stringify(draft)!==draftBaseline.current;
 useBlocker({shouldBlockFn:({next})=>{if(!readEnabled||live.current.owner!==owner)return false;const destination=next.search as Record<string,unknown>;if((ownedPending||sharePending)&&!(next.pathname==='/'&&destination.workspace===workspaceId&&destination.view==='boards'))return !confirm('This change may already be saved. Leave and lose the option to retry it? Select Cancel to stay.');return !leaving.current&&dirty()&&!confirm('Discard unsaved board changes and leave this editor?');},enableBeforeUnload:()=>readEnabled&&live.current.owner===owner&&(!!ownedPending||sharePending||!leaving.current&&dirty())});
 useEffect(()=>{mounted.current=true;return()=>{mounted.current=false;serial.current++;operation.current?.abort();writeOperation.current?.abort();};},[]);
 useEffect(()=>{writeOperation.current?.abort();setWriteBusy(false);setPending(null);setAccepted(null);notified.current=false;pageBack.current=[];},[identity]);
 useEffect(()=>{leaving.current=false;draftBaseline.current=null;serial.current++;operation.current?.abort();setData(null);setDraft(null);setEditing(false);setError('');setNotice('');setBusy(false);if(parsed&&readEnabled)void load();return()=>{serial.current++;operation.current?.abort();};},[owner,readEnabled]);
 useEffect(()=>{if(focus.current){document.getElementById(focus.current)?.focus();focus.current=null;}},[draft]);
 function purge(cause:unknown){if(cause instanceof ApiError&&[401,403,404].includes(cause.status))shareAccessEpoch.current++;setData(null);setDraft(null);setEditing(false);setError(cause instanceof Error?cause.message:'Board access was cleared.');if(cause instanceof ApiError&&cause.status===401&&!notified.current){notified.current=true;live.current.onUnauthorized();}}
 async function load(){if(!mounted.current||!parsed||!readEnabled)return;operation.current?.abort();const ctrl=new AbortController(),token=++serial.current;operation.current=ctrl;setBusy(true);setError('');const valid=()=>mounted.current&&live.current.owner===owner&&live.current.readEnabled&&serial.current===token&&!ctrl.signal.aborted;
  try{if(parsed.create){const response=await read(base(),listSchema,ctrl.signal);if(!valid())return;checkWorkspace(response.workspaceId);setData({owner,role:response.role,item:null,items:[],next:null});const initial=blank();draftBaseline.current=JSON.stringify(initial);setDraft(initial);setEditing(true);}else if(parsed.id){const response=await read(base()+'/'+parsed.id,detailSchema,ctrl.signal);if(!valid())return;checkWorkspace(response.workspaceId);checkItem(response.item,parsed.id);setData({owner,role:response.role,item:response.item,items:[],next:null});setScopeDraft(parsed.scope??response.item.definition.scope);setRefresh(value=>value+1);}else{const response=await read(base()+(parsed.cursor?'?'+new URLSearchParams({cursor:parsed.cursor}):''),listSchema,ctrl.signal);if(!valid())return;checkWorkspace(response.workspaceId);if(new Set(response.items.map(row=>row.id)).size!==response.items.length||response.nextCursor===parsed.cursor&&response.nextCursor!==null)throw new InvalidBoard();setData({owner,role:response.role,item:null,items:response.items,next:response.nextCursor});}}
  catch(cause){if(valid())purge(cause);}finally{if(valid())setBusy(false);}
 }
 const base=()=>'/api/workspaces/'+workspaceId+'/boards';
 function checkWorkspace(value:string){if(value!==workspaceId)throw new InvalidBoard();}
 function checkItem(value:BoardItem,id?:string){if(value.workspaceId!==workspaceId||id!==undefined&&value.id!==id)throw new InvalidBoard();scopeValue(value.definition.scope);}
 function navigate(next:string,discardConfirmed=false){if(dirty()&&!discardConfirmed&&!confirm('Discard unsaved board changes and leave this editor?'))return;leaving.current=true;serial.current++;operation.current?.abort();setData(null);setEditing(false);setDraft(null);setError('');if(next===query){void load();return;}onNavigate(next);}
 function startWrite(operation:Pending['operation']){if(!writer||writeLock.current||ownedPending)return;try{let body:Pending['body']={requestId:crypto.randomUUID()},path=base(),sourceId=item?.id??null;if(operation==='create'||operation==='update'){if(!draft)throw Error('Open the board editor first.');const definition=boardDefinition.parse({...draft,scope:scopeValue(draft.scope)});body={...body,...operation==='update'?{revision:item?.revision}:{},definition};if(operation==='update'){if(!item)throw new InvalidBoard();path+='/'+item.id+'/update';}}else{if(!item)throw new InvalidBoard();body={...body,revision:item.revision,...operation==='clone'?{name:cloneName.trim()}: {}};if(operation==='clone'&&!boardDefinition.shape.name.safeParse(body.name).success)throw Error('Enter a new board name.');path+='/'+item.id+'/'+operation;}
   if(new TextEncoder().encode(JSON.stringify(body)).length>boardLimits.bodyBytes)throw Error('This board is too large. Shorten its content.');const attempt={workspace:workspaceId,user:userId,path,operation,sourceId,body};setPending(attempt);void send(attempt);
  }catch(cause){setError(cause instanceof z.ZodError?'Check the name, card settings and row limits. Each data card needs an available entity or a preserved reference.':cause instanceof Error?cause.message:'Check the board fields.');}}
 async function send(attempt:Pending){if(!writer||writeLock.current||!readEnabled)return;writeLock.current=true;setWriteBusy(true);setError('');writeOperation.current?.abort();const ctrl=new AbortController();writeOperation.current=ctrl;const captured=identity,valid=()=>mounted.current&&live.current.identity===captured&&live.current.readEnabled&&attempt.workspace===workspaceId&&attempt.user===userId&&!ctrl.signal.aborted;
  try{const result=await read(attempt.path,writeSchema,ctrl.signal,attempt.body);if(!valid())return;checkWorkspace(result.workspaceId);if(result.ack.requestId!==attempt.body.requestId||result.ack.operation!==attempt.operation||['update','delete'].includes(attempt.operation)&&result.ack.boardId!==attempt.sourceId||result.ack.appliedRevision!==(attempt.operation==='create'||attempt.operation==='clone'?1:attempt.operation==='delete'?attempt.body.revision:(attempt.body.revision??0)+1)||result.deleted!==(result.item===null)||result.item!==null&&result.item.revision<result.ack.appliedRevision)throw new InvalidBoard();if(result.item)checkItem(result.item,result.ack.boardId);setPending(null);setAccepted({scope:identity,ack:result.ack,deleted:result.deleted});setNotice('Board change accepted.');if(live.current.owner!==owner){setNotice('Board change accepted for its original board. Reload it to see current details.');return;}leaving.current=true;setData({owner:live.current.owner,role:result.role,item:result.item,items:[],next:null});setDraft(null);setEditing(false);if(result.deleted){setNotice('Change accepted; its original board has since been deleted.');navigate('',true);}else if(result.item){onNavigate(new URLSearchParams({board:result.item.id}).toString());setScopeDraft(result.item.definition.scope);setRefresh(value=>value+1);}}
  catch(cause){if(!valid())return;if(cause instanceof InvalidBoard||cause instanceof ApiError&&[401,403,404].includes(cause.status))purge(cause);else setError(cause instanceof Error?cause.message:'The board change remains unconfirmed.');}
  finally{writeLock.current=false;if(mounted.current&&live.current.identity===captured&&writeOperation.current===ctrl)setWriteBusy(false);if(writeOperation.current===ctrl)writeOperation.current=null;}
 }
 function change(next:BoardDefinition){setDraft(next);setNotice('');setError('');}
 return <section className="boards-panel stack" aria-label="Boards" aria-busy={busy||writeBusy}><header className="board-panel-intro"><p className="hint">Arrange charts, metrics and notes from your websites.</p></header>
 {!parsed?<div className="alert" role="alert"><p>This board link is invalid. No boards or card data were read.</p><button className="btn" onClick={()=>navigate('')}>Reset boards</button></div>:!readEnabled?<p role="status">Waiting for the current board route. No private data are being read.</p>:<>
 <div className="row board-toolbar"><button className="btn" disabled={writeBusy} onClick={()=>navigate('')}>All boards</button><button className="btn" disabled={busy||writeBusy} onClick={()=>{if(dirty()&&!confirm('Discard unsaved board changes and reload the current saved version?'))return;setDraft(null);setEditing(false);void load();}}>Reload current access</button>{writer&&current&&!item&&!editing&&current.items.length>0&&<button className="btn primary board-create-button" disabled={!!ownedPending} onClick={()=>navigate('new=1')}>New board</button>}</div>{busy&&<p role="status">Loading boards…</p>}{error&&<div role="alert" className="alert">{error}</div>}{notice&&<p role="status">{notice}</p>}
 {accepted?.scope===identity&&<p className="banner" role="status">Verified {accepted.ack.operation} acknowledgment · board {accepted.ack.boardId} · applied revision {accepted.ack.appliedRevision}.{accepted.deleted?' The acknowledged board is now deleted.':' This receipt is separate from any later read of the current board.'}</p>}
 {ownedPending&&<div className="banner" role="status"><p>A {ownedPending.operation} request is awaiting its exact acknowledgment. Reloading cannot confirm it.</p><div className="row"><button className="btn" disabled={!writer||writeBusy||busy} onClick={()=>void send(ownedPending)}>Retry same board request</button><button className="btn" disabled={writeBusy} onClick={()=>{setPending(null);setNotice('Retry discarded. The earlier change may have completed. Reload before a new change.');}}>Discard board retry</button></div></div>}
 {current&&!item&&!editing&&<><ul className="board-list">{current.items.map(row=><li className="card" key={row.id}><h3><button className="board-open" onClick={()=>navigate(new URLSearchParams({board:row.id}).toString())}>{row.name}</button></h3><p>{row.description}</p><p className="hint">Revision {row.revision} · Updated <time dateTime={row.updatedAt}>{new Date(row.updatedAt).toLocaleString()}</time></p></li>)}</ul>{current.items.length===0&&<section className="card board-empty-state" aria-label="No boards"><h3>{parsed?.cursor?'No boards on this page':'Your first board starts here'}</h3><p>Arrange charts, metrics and notes from your websites.</p>{writer&&<button className="btn primary" disabled={!!ownedPending} onClick={()=>navigate('new=1')}>New board</button>}</section>}{(current.items.length>0||parsed?.cursor||pageBack.current.length>0)&&<div className="row board-pagination"><button className="btn" disabled={!pageBack.current.length||busy} onClick={()=>navigate(pageBack.current.pop()??'')}>Previous boards</button><button className="btn" disabled={!current.next||busy} onClick={()=>{if(current.next){pageBack.current.push(query);navigate(new URLSearchParams({cursor:current.next}).toString());}}}>Next 20 boards</button></div>}</>}
 {item&&!editing&&<><header><h3>{item.definition.name}</h3><p>{item.definition.description}</p><p className="hint">Saved revision {item.revision}. Applied dates and filters below can differ from the saved default.</p></header>{writer&&<div className="row"><button className="btn" disabled={!!ownedPending||writeBusy||item.revision===2147483647} onClick={()=>{leaving.current=false;draftBaseline.current=JSON.stringify(item.definition);setDraft(structuredClone(item.definition));setEditing(true);}}>Edit board</button><label>New clone name<input maxLength={120} value={cloneName} onChange={event=>setCloneName(event.target.value)}/></label><button className="btn" disabled={!!ownedPending||writeBusy||!cloneName.trim()} onClick={()=>startWrite('clone')}>Clone board</button><button className="btn danger" disabled={!!ownedPending||writeBusy} onClick={()=>{if(confirm('Delete this board? Its exact earlier request receipts remain available.'))startWrite('delete');}}>Delete board</button></div>}
 <ScopeFields value={scopeDraft} onChange={setScopeDraft}/><button className="btn primary" disabled={busy||writeBusy} onClick={()=>{try{const scope=scopeValue(scopeDraft);onNavigate(new URLSearchParams({board:item.id,scope}).toString());setRefresh(value=>value+1);}catch(cause){setError(cause instanceof Error?cause.message:'Check applied scope.');}}}>Apply board scope</button>
 {applied&&<BoardView item={item} projects={projects} scope={applied} owner={owner} enabled={readEnabled} refresh={refresh} onRole={role=>setData(old=>old?.owner===owner?{...old,role:old.role==='viewer'?'viewer':role}:old)} onAccessLoss={purge}/>}
 </>}
 {editing&&draft&&current&&<><BoardEditor value={draft} projects={projects} workspaceId={workspaceId} previewOwner={JSON.stringify([owner,current?.role])} previewEnabled={readEnabled&&current!==null} onRole={role=>setData(old=>old?.owner===owner?{...old,role:old.role==='viewer'?'viewer':role}:old)} onAccessLoss={purge} disabled={!writer||writeBusy||!!ownedPending} onChange={change} uid={uid} onMove={(id,message)=>{focus.current=id;setNotice(message);}}/><div className="row"><button className="btn primary" disabled={!writer||writeBusy||!!ownedPending} onClick={()=>startWrite(item?'update':'create')}>Save board</button><button className="btn" disabled={writeBusy} onClick={()=>{setEditing(false);setDraft(null);if(!item)navigate('',true);}}>Cancel editing</button></div><p className="hint">Previews show current data for the draft card. They never save or replace the saved board.</p></>}
 </>}
 <BoardShareManager key={identity} accessEpoch={shareAccessEpoch} workspaceId={workspaceId} userId={userId} item={item} currentRole={current?.role??null} owner={owner} enabled={readEnabled&&current!==null&&!editing} onRole={role=>setData(old=>old?.owner===owner?{...old,role:old.role==='viewer'?'viewer':role}:old)} onAccessLoss={purge} onPendingChange={setSharePending}/>
 </section>;
